fixtures.raw:
{
  "options": [
    {
      "widgetType": "excerpt",
      "config": {
        "article": "Marie Curie",
        "project": "en.wikipedia"
      },
      "reason": "Displays the lead paragraph and summary of the Marie Curie article."
    },
    {
      "widgetType": "speaker",
      "config": {
        "text": "",
        "source": "excerpt",
        "lang": "en",
        "speakOnChange": true
      },
      "reason": "Reads the text from the Excerpt widget aloud; set the source to the Excerpt widget on your board to connect them."
    }
  ]
}

{
  "options": [
    {
      "widgetType": "excerpt",
      "config": {
        "article": "Albert Einstein",
        "project": "en.wikipedia"
      },
      "reason": "Fetches the article summary to serve as the source text for translation."
    },
    {
      "widgetType": "translate",
      "config": {
        "text": "{{widget:excerpt}}",
        "from": "en",
        "to": "fr",
        "display": "translation"
      },
      "reason": "Translates the summary from the Excerpt widget into French."
    },
    {
      "widgetType": "speaker",
      "config": {
        "source": "translate#speech",
        "speakOnChange": true
      },
      "reason": "Speaks the French translation aloud, using the language metadata from the Translator to pick the correct voice."
    }
  ]
}

{
  "options": [
    {
      "widgetType": "boardControls",
      "config": {
        "title": "Institution Selector",
        "spec": "category | buttons | Collection | Images from the Metropolitan Museum of Art, Images from the Library of Congress"
      },
      "reason": "This controller creates a button menu to switch the board parameter {{category}} between the two institutions, driving the other widgets."
    },
    {
      "widgetType": "glamorgan",
      "config": {
        "category": "{{category}}",
        "depth": 1,
        "year": 2026,
        "month": 5,
        "fileBudget": 500,
        "topN": 5
      },
      "reason": "GLAM Category Usage calculates live impact stats (files, pages, views) for the selected Commons category."
    },
    {
      "widgetType": "cimSnapshot",
      "config": {
        "category": "{{category}}",
        "scope": "deep",
        "month": 5
      },
      "reason": "CIM Category Snapshot provides precomputed, high-performance metrics for the selected category if it is registered in the CIM system."
    }
  ]
}
